mapper.select:
SELECT o.id, o.order_no, o.amount, o.status, o.payment_status, o.trading_order_no, o.estimated_arrival_time, o.create_time, e.name AS elder_name, e.bed_number, np.name AS project_name, np.image AS project_image, m.name AS member_name FROM `order` o LEFT JOIN elder e ON o.elder_id = e.id LEFT JOIN nursing_project np ON o.project_id = np.id LEFT JOIN member m ON o.member_id = m.id WHERE o.view_status = '0'
AND o.status = #{status}
ORDER BY o.create_time DESC

sql.where:
o.view_status = '0'

    AND o.status = #{status}


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND e.name LIKE CONCAT('%', #{elderlyName}, '%')


    AND u.real_name LIKE CONCAT('%', #{creator}, '%')


    AND o.create_time >= #{startTime}


    AND o.create_time <= #{endTime}

mapper.select:
SELECT rr.id, rr.refund_no AS refundNo, rr.product_order_no AS orderNo, rr.refund_amount AS refundAmount, rr.refund_status AS refundStatus, rr.refund_msg AS refundMsg, rr.memo, rr.create_time AS createTime, rr.update_time AS updateTime, o.amount AS orderAmount, e.name AS elderName, np.name AS projectName, u.real_name AS creator FROM refund_record rr INNER JOIN `order` o ON rr.product_order_no = o.order_no LEFT JOIN elder e ON o.elder_id = e.id LEFT JOIN nursing_project np ON o.project_id = np.id LEFT JOIN sys_user u ON rr.create_by = u.id
AND rr.refund_status = #{refundStatus}
AND rr.refund_no LIKE CONCAT('%', #{refundNoStr}, '%')
AND rr.product_order_no LIKE CONCAT('%', #{orderNo}, '%')
AND u.real_name LIKE CONCAT('%', #{creator}, '%')
AND rr.create_time >= #{startTime}
AND rr.create_time <= #{endTime}
ORDER BY rr.create_time DESC
